import{_ as l,a0 as s,w as L,s as S,ao as a,I as n,x as r,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"把 SQL Server 遷移到 Linux？不如換成 MySQL | LCTT x X-CMD","titleTemplate":false,"description":"把 SQL Server 遷移到 Linux？不如換成 MySQL | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"把 SQL Server 遷移到 Linux？不如換成 MySQL | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"把 SQL Server 遷移到 Linux？不如換成 MySQL | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20161128 Moving with SQL Server to Linux - Move from SQL Server to MySQL as well","title":"把 SQL Server 遷移到 Linux？不如換成 MySQL","tag":"201612","desc":""},"relativePath":"201612/20161128 Moving with SQL Server to Linux - Move from SQL Server to MySQL as well.md","filePath":"[post].md"}'),p={name:"201612/20161128 Moving with SQL Server to Linux - Move from SQL Server to MySQL as well.md"};function u(d,e,x,m,v,Q){const t=s("Link");return L(),S("div",null,[e[16]||(e[16]=a('<h1 id="把-sql-server-遷移到-linux-不如換成-mysql" tabindex="-1">把 SQL Server 遷移到 Linux？不如換成 MySQL <a class="header-anchor" href="#把-sql-server-遷移到-linux-不如換成-mysql" aria-label="Permalink to “把 SQL Server 遷移到 Linux？不如換成 MySQL”">​</a></h1><p>最近幾年，數量龐大的個人和組織放棄 Windows 平台選擇 Linux 平台，而且隨着人們體驗到更多 Linux 的發展，這個數字將會繼續增長。在很長的一段時間內， Linux 是網絡服務器的領導者，因為大部分的網絡服務器都運行在 Linux 之上，這或許是為什麼那麼多的個人和組織選擇遷移的一個原因。</p><p>遷移的原因有很多，更強的平台穩定性、可靠性、成本、所有權和安全性等等。隨着更多的個人和組織遷移到 Linux 平台，MS SQL 服務器資料庫管理系統的遷移也有着同樣的趨勢，首選的是 MySQL ，這是因為 MySQL 的互用性、平台無關性和購置成本低。</p><p>有如此多的個人和組織完成了遷移，這是應業務需求而產生的遷移，而不是為了遷移的樂趣。因此，有必要做一個綜合可行性和成本效益分析，以瞭解遷移對於你的業務上的正面和負面影響。</p><p>遷移需要基於以下重要因素：</p><h3 id="對平台的掌控" tabindex="-1">對平台的掌控 <a class="header-anchor" href="#對平台的掌控" aria-label="Permalink to “對平台的掌控”">​</a></h3><p>不像 Windows 那樣，你不能完全控制版本發佈和修復，而 Linux 可以讓你需要需要修復的時候真正給了你獲取修復的靈活性。這一點受到了開發者和安全人員的喜愛，因為他們能在一個安全威脅被確定時立即自行打補丁，不像 Windows ，你只能期望官方儘快發佈補丁。</p><h3 id="跟隨大眾" tabindex="-1">跟隨大眾 <a class="header-anchor" href="#跟隨大眾" aria-label="Permalink to “跟隨大眾”">​</a></h3><p>目前， 運行在 Linux 平台上的服務器在數量上遠超 Windows，幾乎是全世界服務器數量的四分之三，而且這種趨勢在最近一段時間內不會改變。因此，許多組織正在將他們的服務完全遷移到 Linux 上，而不是同時使用兩種平台，同時使用將會增加他們的運營成本。</p><h3 id="微軟沒有開放-sql-server-的源代碼" tabindex="-1">微軟沒有開放 SQL Server 的源代碼 <a class="header-anchor" href="#微軟沒有開放-sql-server-的源代碼" aria-label="Permalink to “微軟沒有開放 SQL Server 的源代碼”">​</a></h3><p>微軟宣稱他們下一個名為 Denali 的新版 MS SQL Server 將會是一個 Linux 版本，並且不會開放其源代碼，這意味着他們仍然使用的是軟件授權模式，只是新版本將能在 Linux 上運行而已。這一點將許多樂於接受開源新版本的人拒之門外。</p>',11)),n("p",null,[e[1]||(e[1]=r("這也沒有給那些使用閉源的 Oracle 用户另一個選擇，對於使用完全開源的 ",-1)),i(t,{href:"http://www.scalearc.com/how-it-works/products/scalearc-for-mysql"},{default:o(()=>[...e[0]||(e[0]=[r("MySQL 用户",-1)])]),_:1}),e[2]||(e[2]=r("也是如此。",-1))]),e[17]||(e[17]=a('<h3 id="節約授權許可證的花費" tabindex="-1">節約授權許可證的花費 <a class="header-anchor" href="#節約授權許可證的花費" aria-label="Permalink to “節約授權許可證的花費”">​</a></h3><p>授權許可證的潛在成本讓許多用户很失望。在 Windows 平台上運行 MS SQL 服務器有太多的授權許可證牽涉其中。你需要這些授權許可證：</p><ul><li>Windows 操作系統</li><li>MS SQL 服務器</li><li>特定的資料庫工具，例如 SQL 分析工具等</li></ul><p>不像 Windows 平台，Linux 完全沒有高昂的授權花費，因此更能吸引用户。 MySQL 資料庫也能免費獲取，甚而它提供了像 MS SQL 服務器一樣的靈活性，那就更值得選擇了。不像那些給 MS SQL 設計的收費工具，大部分的 MySQL 資料庫實用程序是免費的。</p><h3 id="有時候用的是特殊的硬件" tabindex="-1">有時候用的是特殊的硬件 <a class="header-anchor" href="#有時候用的是特殊的硬件" aria-label="Permalink to “有時候用的是特殊的硬件”">​</a></h3><p>因為 Linux 是不同的開發者所開發，並在不斷改進中，所以它獨立於所運行的硬件之上，並能被廣泛使用在不同的硬件平台。然而儘管微軟正在努力讓 Windows 和 MSSQL 服務器做到硬件無關，但在平台無關上依舊有些限制。</p><h3 id="支持" tabindex="-1">支持 <a class="header-anchor" href="#支持" aria-label="Permalink to “支持”">​</a></h3><p>有了 Linux、MySQL 和其它的開源軟件，獲取滿足自己特定需求的幫助變得更加簡單，因為有不同開發者參與到這些軟件的開發過程中。這些開發者或許就在你附近，這樣更容易獲取幫助。在線論壇也能幫上不少，你能發帖並討論你所面對的問題。</p><p>至於那些商業軟件，你只能根據他們的軟件協議和時間來獲得幫助，有時候他們不能在你的時間範圍內給出一個解決方案。</p><p>在不同的情況中，遷移到 Linux 都是你最好的選擇，加入一個徹底的、穩定可靠的平台來獲取優異表現，眾所周知，它比 Windows 更健壯。這值得一試。</p><hr>',11)),n("p",null,[e[4]||(e[4]=r("via: ",-1)),i(t,{href:"https://www.howtoforge.com/tutorial/moving-with-sql-server-to-linux-move-from-sql-server-to-mysql-as-well/"},{default:o(()=>[...e[3]||(e[3]=[r("https://www.howtoforge.com/tutorial/moving-with-sql-server-to-linux-move-from-sql-server-to-mysql-as-well/",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=r("作者：",-1)),i(t,{href:"https://twitter.com/howtoforgecom"},{default:o(()=>[...e[5]||(e[5]=[r("Tony Branson",-1)])]),_:1}),e[9]||(e[9]=r(" 譯者：",-1)),i(t,{href:"https://github.com/ypingcn"},{default:o(()=>[...e[6]||(e[6]=[r("ypingcn",-1)])]),_:1}),e[10]||(e[10]=r(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[7]||(e[7]=[r("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=r("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[11]||(e[11]=[r("LCTT",-1)])]),_:1}),e[14]||(e[14]=r(" 組織編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:o(()=>[...e[12]||(e[12]=[r("Linux中國",-1)])]),_:1}),e[15]||(e[15]=r(" 榮譽推出",-1))])])}const h=l(p,[["render",u]]);export{M as __pageData,h as default};
